"""Disjoint delivery, incremental-retention and optional-investment accounting.

Amounts are USD micro-units, not token movements. Signed attestations retain
their evidence and uncertainty; they are not bank or provider attestations.
"""

from __future__ import annotations

from typing import Any, Callable, Literal

from pydantic import Field, model_validator

from ..store import Conflict, Journal, digest as runtime_digest
from .protocol import MAX_JSON_BYTES, MAX_JSON_NODES, Digest, Identifier, StrictModel, Text, canonical, digest
from .trust import SignedEnvelope, TrustRegistry
from .flywheel_checkpoint import DurableCheckpoint
from .flywheel_customer import MODES, CustomerDeposit, CustomerEarning, CustomerRefund, balances, summarize
from .transformation_library import _is_exact_type

KEY = "@flywheel-costs:v1"
CATEGORIES = {"model", "tools", "compute", "storage", "network", "human", "acceptance", "correction", "overhead"}
MAX_OPERATION_CACHE = 128
MAX_PAYMENT_CACHE = 32
CHARGE_COMPLETION_BYTES = 40_960


def accepted_native_delivery(journal: Journal, mission_id: str, cx: Any = None) -> dict[str, Any]:
    """Read actual native completion and its bound approval, never a synthetic status flag."""
    from ..models import Mission, Research
    from ..work import verify_result

    record = journal.latest(mission_id, cx)
    review = record.get("review", {})
    if (
        record.get("state") != "completed"
        or review.get("approved") is not True
        or review.get("result_hash") != runtime_digest(record.get("result"))
        or record.get("request_hash") != runtime_digest(record.get("request"))
    ):
        raise ValueError("origin requires exact completed and approved native delivery")
    mission = Mission.model_validate(record["request"])
    if not isinstance(mission.work, Research):
        raise ValueError("this protected slice supports native public-source research delivery only")
    verify_result(mission, record["result"])
    return record


class Charge(StrictModel):
    activity_id: Identifier
    mission_id: Identifier
    bucket: Literal["A", "B", "C"]
    category: Literal[
        "model", "tools", "compute", "storage", "network", "human", "acceptance", "correction", "overhead"
    ]
    accrued_micro_usd: int | None = Field(ge=0, le=10**15)
    paid_micro_usd: int = Field(ge=0, le=10**15)
    basis: Literal["measured", "attested", "unknown"]
    evidence_digest: Digest
    note: Text

    @model_validator(mode="after")
    def complete_amount(self) -> Charge:
        if (self.accrued_micro_usd is None) != (self.basis == "unknown"):
            raise ValueError("unknown costs must stay unknown rather than becoming zero")
        if self.accrued_micro_usd is not None and self.paid_micro_usd > self.accrued_micro_usd:
            raise ValueError("paid cost exceeds its complete accrual")
        return self


class Payment(StrictModel):
    payment_id: Identifier
    activity_id: Identifier
    amount_micro_usd: int = Field(gt=0, le=10**15)
    evidence_digest: Digest


class CompletenessSeal(StrictModel):
    mission_id: Identifier
    evidence_digest: Digest
    categories: list[str] = Field(min_length=9, max_length=9)

    @model_validator(mode="after")
    def exact_categories(self) -> CompletenessSeal:
        if set(self.categories) != CATEGORIES:
            raise ValueError("completeness requires exactly every resource category")
        return self


class CostLedger:
    """Use the existing atomic journal and configured accounting authority."""

    def __init__(self, journal: Journal, trust: TrustRegistry) -> None:
        self.journal, self.trust = journal, trust
        self.checkpoint: DurableCheckpoint | None = None
        self.custody_check: Callable[[], None] | None = None
        self.general_delivery_check: Callable[[str, Any], dict[str, Any]] | None = None
        with journal.transaction() as cx:
            try:
                journal.latest(KEY, cx)
            except KeyError:
                journal.append(
                    cx,
                    KEY,
                    {
                        "charges": {},
                        "receipts": {},
                        "offers": {},
                        "capital": {},
                        "reserve_micro_usd": 0,
                        "seals": {},
                        "reuse_seals": {},
                        "operations": {},
                    },
                )

    def snapshot(self, cx: Any = None) -> dict[str, Any]:
        if self.custody_check is not None:
            self.custody_check()
        if self.checkpoint is not None:
            if cx is None:
                with self.journal.transaction() as connection:
                    return self.snapshot(connection)
            self.checkpoint.verify(self.journal, cx)
        return self.journal.document(self.journal.latest(KEY, cx))

    def current_signature(self, raw: Any, domain: str, role: str) -> dict[str, Any]:
        signed = SignedEnvelope.model_validate(raw)
        payload = self.trust.verify(signed, domain, role)
        if payload.get("journal_identity") != self.journal.identity:
            raise ValueError("supporting signature belongs to a different journal")
        return dict(payload)

    def _invocation_reservation(self, row: dict[str, Any], charge: Charge, cx: Any) -> None:
        from eth_account import Account
        from eth_account.messages import encode_defunct
        from eth_keys.exceptions import BadSignature

        from ..chain import address
        from .flywheel_access import AccessRequest, ServiceIdentity, direct_name
        from .flywheel_capsules import Invocation, input_digest
        from .flywheel_specialists import PlacementInvocation

        if (
            charge.activity_id != "reuse/" + charge.mission_id
            or charge.bucket != "B"
            or charge.category != "compute"
            or charge.accrued_micro_usd is not None
            or charge.paid_micro_usd != 0
            or charge.basis != "unknown"
            or "original" in row
        ):
            raise ValueError("unsigned cost row is not an original protected invocation reservation")
        stored = self.journal.latest("@flywheel-invocation:" + charge.mission_id, cx)
        raw, receipt = stored["request"], stored["receipt"]
        request = PlacementInvocation.model_validate(raw) if "problem" in raw else Invocation.model_validate(raw)
        request_hash = digest("flywheel-invocation", request)
        attempt_hash = digest(
            "flywheel-invocation-attempt",
            {
                "candidate_digest": receipt["candidate_digest"],
                "mission_id": request.mission_id,
                "request_digest": request_hash,
            },
        )
        document = request.problem if isinstance(request, PlacementInvocation) else request.document
        if (
            request.mission_id != charge.mission_id
            or receipt["request_digest"] != request_hash
            or receipt["attempt_digest"] != attempt_hash
            or charge.evidence_digest != attempt_hash
            or receipt["input_digest"] != input_digest(document)
            or any(
                receipt[name] != getattr(request, name)
                for name in ("beta_digest", "policy_digest", "recipient_capabilities_digest", "cost_cap_micro_usd")
            )
        ):
            raise ValueError("cost reservation differs from its durable invocation request")
        authority = receipt["authorization"]
        challenge = self.journal.latest("@flywheel-challenge:" + authority["challenge_id"], cx)
        payload = challenge["payload"]
        proof = AccessRequest(challenge_id=authority["challenge_id"], signature=challenge["signature"])
        message = (
            "AGI Alpha resource authorization v1\n"
            + canonical(payload).decode()
            + "\nNo spending, settlement, deployment or external-system authority."
        )
        if (
            set(payload)
            != {
                "service",
                "journal_identity",
                "name",
                "wallet",
                "resource",
                "action",
                "request_digest",
                "issued_at",
                "expires_at",
                "nonce",
            }
            or ServiceIdentity.model_validate(payload["service"]).model_dump() != payload["service"]
            or digest("flywheel-challenge", payload) != proof.challenge_id
            or challenge["message"] != message
            or challenge["used"] is not True
            or challenge["authorization"] != authority
            or challenge["revision"] >= stored["revision"]
            or payload["journal_identity"] != self.journal.identity
            or payload["resource"] != receipt["candidate_digest"]
            or payload["action"] != "invoke"
            or payload["request_digest"] != request_hash
            or direct_name(payload["name"]) != authority["name"]
            or payload["wallet"] != authority["wallet"]
            or authority["request_committed_at"] != payload["issued_at"]
            or type(authority["checked_at"]) is not int
            or not payload["issued_at"] <= authority["checked_at"] < payload["expires_at"]
            or type(receipt["started_at"]) is not int
            or receipt["started_at"] < authority["checked_at"]
        ):
            raise ValueError("invocation cost lacks its exact consumed historical authorization")
        try:
            signer = address(Account.recover_message(encode_defunct(text=message), signature=proof.signature))
        except (ValueError, TypeError, BadSignature) as exc:
            raise ValueError("historical invocation wallet signature is invalid") from exc
        if signer != payload["wallet"]:
            raise ValueError("historical invocation wallet signature differs from the consumed challenge")

    def _current_charge(self, row: dict[str, Any], cx: Any, depth: int = 0) -> None:
        if depth > 1:
            raise ValueError("cost reconciliation has unsupported ancestry")
        from .flywheel_execution import ExecutionPermit, operation_key

        charge = Charge.model_validate({name: row[name] for name in Charge.model_fields})
        if row["signed"] is None:
            self._invocation_reservation(row, charge, cx)
            return
        signed = SignedEnvelope.model_validate(row["signed"])
        if signed.domain == "flywheel-cost-command":
            payload = self.current_signature(signed.model_dump(), "flywheel-cost-command", "accounting")
            original = Charge.model_validate(payload["record"])
            if (
                set(payload) != {"journal_identity", "operation_id", "action", "record"}
                or payload["action"] != ("resolve" if "original" in row else "charge")
                or original.model_dump(exclude={"paid_micro_usd"}) != charge.model_dump(exclude={"paid_micro_usd"})
                or original.paid_micro_usd > charge.paid_micro_usd
            ):
                raise ValueError("cost row differs from its signed accounting command")
        elif signed.domain == "flywheel-execution-permit":
            payload = self.current_signature(signed.model_dump(), "flywheel-execution-permit", "controller")
            permit = ExecutionPermit.model_validate(payload["permit"])
            execution = self.journal.latest(operation_key(permit.operation_id), cx)
            if (
                set(payload) != {"journal_identity", "permit"}
                or charge.activity_id != "execution/" + permit.operation_id
                or charge.mission_id != execution["mission"]["mission_id"]
                or charge.bucket != permit.bucket
                or charge.category != "model"
                or charge.accrued_micro_usd is not None
                or charge.paid_micro_usd != 0
                or execution["permit"] != signed.model_dump()
                or "original" in row
            ):
                raise ValueError("cost reservation differs from its actual signed execution")
        elif signed.domain == "flywheel-gym-plan":
            from .flywheel_gym import KEY as GYM_KEY, GymPlan

            payload = self.current_signature(signed.model_dump(), "flywheel-gym-plan", "controller")
            plan = GymPlan.model_validate(payload["plan"])
            campaign = self.journal.latest(GYM_KEY + plan.campaign_id, cx)
            if (
                set(payload) != {"journal_identity", "plan"}
                or charge.activity_id != "gym/" + plan.campaign_id
                or charge.mission_id != plan.mission_id
                or charge.bucket != "C"
                or charge.category != "compute"
                or charge.accrued_micro_usd is not None
                or charge.paid_micro_usd != 0
                or charge.evidence_digest != digest("gym-plan", plan)
                or campaign["plan"] != signed.model_dump()
                or "original" in row
            ):
                raise ValueError("cost reservation differs from its actual signed Gym campaign")
        else:
            raise ValueError("cost signature has an unsupported authority domain")
        if "original" in row:
            if any(row[name] != row["original"][name] for name in ("activity_id", "mission_id", "bucket", "category")):
                raise ValueError("cost reconciliation differs from its original reservation")
            self._current_charge(row["original"], cx, depth + 1)

    def require_current_evidence(self, mission_id: str, buckets: list[str], cx: Any) -> None:
        """Recheck supporting authority before a new protected use; leave history unchanged."""
        ledger = self.snapshot(cx)
        for row in ledger["charges"].values():
            if row["mission_id"] == mission_id and row["bucket"] in buckets:
                self._current_charge(row, cx)
        for bucket in buckets:
            name = {"A": "seals", "B": "reuse_seals", "C": "investment_seals"}[bucket]
            seal = ledger.get(name, {}).get(mission_id)
            if seal is None:
                continue
            payload = self.current_signature(seal["signed"], "flywheel-cost-command", "accounting")
            allowed = {"A": {"seal"}, "B": {"seal-reuse", "seal-retention"}, "C": {"seal-investment"}}[bucket]
            if (
                set(payload) != {"journal_identity", "operation_id", "action", "record"}
                or payload["action"] not in allowed
                or CompletenessSeal.model_validate(payload["record"]).model_dump()
                != {name: seal[name] for name in CompletenessSeal.model_fields}
            ):
                raise ValueError("completeness seal differs from its signed accounting command")

    @staticmethod
    def require_open(state: dict[str, Any], mission_id: str, bucket: str) -> None:
        seals = (
            state["seals"]
            if bucket == "A"
            else state.get("reuse_seals", {})
            if bucket == "B"
            else state.get("investment_seals", {})
        )
        if mission_id in seals:
            raise Conflict("sealed cost records cannot acquire another invocation or activity")

    @staticmethod
    def _nodes(value: Any) -> int:
        pending = [value]
        count = 0
        while pending:
            item = pending.pop()
            count += 1
            if isinstance(item, dict):
                pending.extend(item.values())
            elif isinstance(item, list):
                pending.extend(item)
        return count

    def _persist(self, cx: Any, state: dict[str, Any]) -> None:
        """Reserve worst-case bounded reconciliation before any new paid work."""
        rows = list(state["charges"].values())
        seals = {"A": state["seals"], "B": state.get("reuse_seals", {}), "C": state.get("investment_seals", {})}
        groups: dict[tuple[str, str], set[str]] = {}
        for row in rows:
            if row["mission_id"] not in seals[row["bucket"]]:
                groups.setdefault((row["mission_id"], row["bucket"]), set()).add(row["category"])
        unknown = sum(row["accrued_micro_usd"] is None for row in rows)
        missing = sum(len(CATEGORIES - categories) for categories in groups.values())
        operations, payments = state["operations"], state.get("payments", {})
        # Working caches always have this finite budget, regardless of current fill.
        reserve_bytes = (
            16_384
            + 256 * len(state.get("customer_deposits", {}))
            + CHARGE_COMPLETION_BYTES * (unknown + missing)
            + 4096 * len(groups)
            + 32_768
            - len(canonical(operations))
            + 262_144
            - len(canonical(payments))
        )
        reserve_nodes = (
            512 + 128 * (unknown + missing + len(groups)) + 129 - self._nodes(operations) + 2048 - self._nodes(payments)
        )
        for row in rows:
            if row["accrued_micro_usd"] is None or row["paid_micro_usd"] < row["accrued_micro_usd"]:
                summary = {"paid_micro_usd": row["paid_micro_usd"]}
                if "payment_count" in row:
                    summary["payment_count"] = row["payment_count"]
                reserve_bytes += 128 - len(canonical(summary))
                reserve_nodes += 2 - int("payment_count" in row)
        if (
            len(operations) > MAX_OPERATION_CACHE
            or len(payments) > MAX_PAYMENT_CACHE
            or reserve_bytes < 0
            or reserve_nodes < 0
        ):
            raise Conflict("accounting working caches require durable compaction")
        state["reserved_capacity_bytes"], state["reserved_capacity_nodes"] = reserve_bytes, reserve_nodes
        if (
            len(canonical(state)) + reserve_bytes > MAX_JSON_BYTES
            or self._nodes(state) + reserve_nodes > MAX_JSON_NODES
        ):
            raise Conflict("accounting capacity preserves outstanding reconciliation and completeness reserves")
        self.journal.append(cx, KEY, state)

    def _remember_operation(
        self, cx: Any, state: dict[str, Any], operation: str, binding: str, signed: SignedEnvelope
    ) -> None:
        self.journal.append(
            cx, "@flywheel-accounting-operation:" + operation, {"binding": binding, "signed": signed.model_dump()}
        )
        operations = state["operations"]
        operations[operation] = binding
        while len(operations) > MAX_OPERATION_CACHE:
            old = next(iter(operations))
            old_binding = operations.pop(old)
            try:
                self.journal.latest("@flywheel-accounting-operation:" + old, cx)
            except KeyError:
                self.journal.append(cx, "@flywheel-accounting-operation:" + old, {"binding": old_binding})

    def _remember_payment(self, cx: Any, payment_id: str, payment: dict[str, Any]) -> None:
        self.journal.append(cx, "@flywheel-payment:" + payment_id, payment)
        self.journal.append(cx, "@flywheel-payment-evidence:" + payment["evidence_digest"], {"payment_id": payment_id})

    def _customer_evidence_unused(self, state: dict[str, Any], evidence: str, cx: Any) -> None:
        if any(row["evidence_digest"] == evidence for kind in ("capital", "receipts") for row in state[kind].values()):
            raise Conflict("incoming funding evidence already allocated")
        for current in state["charges"].values():
            for version in (current, current.get("original", {})):
                if version.get("paid_micro_usd", 0) > 0 and version["evidence_digest"] == evidence:
                    raise Conflict("paid cost evidence already allocated")
        for key in ("@flywheel-customer-evidence:" + evidence, "@flywheel-payment-evidence:" + evidence):
            try:
                self.journal.latest(key, cx)
            except KeyError:
                continue
            raise Conflict("customer or cost payment evidence already allocated")

    def _reserve_paid_cost_evidence(self, record: dict[str, Any], cx: Any) -> None:
        """Check customer allocation before preserving a paid cost version in this ledger."""
        if record["paid_micro_usd"] == 0:
            return
        try:
            self.journal.latest("@flywheel-customer-evidence:" + record["evidence_digest"], cx)
        except KeyError:
            return
        raise Conflict("customer payment evidence already allocated")

    def _customer(self, state: dict[str, Any], action: str, record: Any, signed: SignedEnvelope, cx: Any) -> None:
        deposits = state.setdefault("customer_deposits", {})
        if action == "customer-deposit":
            terms = CustomerDeposit.model_validate(record)
            identity = terms.receipt_id
            try:
                self.journal.latest("@flywheel-customer-event:" + identity, cx)
            except KeyError:
                pass
            else:
                raise Conflict("customer event identity already allocated")
            if identity in deposits or any(identity in state[kind] for kind in ("capital", "receipts", "offers")):
                raise Conflict("customer receipt identity already allocated")
            if len(deposits) >= 256:
                raise Conflict("bounded customer receipt capacity reached")
            self._customer_evidence_unused(state, terms.evidence_digest, cx)
            same_mission = [row["terms"] for row in deposits.values() if row["terms"]["mission_id"] == terms.mission_id]
            if any(row["mode"] != terms.mode for row in same_mission):
                raise ValueError("customer evidence mode cannot change within a mission")
            services = [row for row in same_mission if row["purpose"] == "service"]
            if terms.purpose == "service" and (
                any(row["service_price_micro_usd"] != terms.service_price_micro_usd for row in services)
                or sum(row["amount_micro_usd"] for row in services) + terms.amount_micro_usd
                > terms.service_price_micro_usd
            ):
                raise ValueError("mission deposits exceed or change the frozen total service price")
            deposits[identity] = {
                "terms": terms.model_dump(),
                "earned_micro_usd": 0,
                "refunded_micro_usd": 0,
                "earned_refund_micro_usd": 0,
                "pending_unearned_refund_micro_usd": 0,
                "pending_earned_refund_micro_usd": 0,
                "pending_pass-through_refund_micro_usd": 0,
                "signed": signed.model_dump(),
            }
            evidence = terms.evidence_digest
        else:
            event = (
                CustomerEarning.model_validate(record)
                if action == "customer-earn"
                else CustomerRefund.model_validate(record)
            )
            identity = event.event_id
            try:
                self.journal.latest("@flywheel-customer-event:" + identity, cx)
            except KeyError:
                pass
            else:
                raise Conflict("customer event identity already allocated")
            if event.receipt_id not in deposits:
                raise ValueError("customer event requires its exact recorded receipt")
            row = deposits[event.receipt_id]
            amounts = balances(row)
            evidence = None
            if isinstance(event, CustomerEarning):
                if row["terms"]["purpose"] != "service" or event.amount_micro_usd > (
                    amounts["unearned_service"] - row.get("pending_unearned_refund_micro_usd", 0)
                ):
                    raise ValueError("earning requires sufficient unearned service funds; custody is never revenue")
                mission_id = row["terms"]["mission_id"]
                if event.delivery_kind == "native":
                    delivery = accepted_native_delivery(self.journal, mission_id, cx)
                    accepted_digest = digest("native-delivery-review", delivery["review"])
                    if row["terms"]["mode"] == "live":
                        raise ValueError("native live commercial evidence mode is not qualified by this adapter")
                else:
                    if self.general_delivery_check is None or event.operation_id is None:
                        raise ValueError("general earning requires the existing protected acceptance service")
                    delivery = self.general_delivery_check(event.operation_id, cx)
                    if delivery["mission"]["mission_id"] != mission_id:
                        raise ValueError("customer funds and accepted execution identify different missions")
                    from .flywheel_learning import ACCEPTANCE_KEY

                    accepted_digest = self.journal.latest(ACCEPTANCE_KEY + event.operation_id, cx)["digest"]
                    if row["terms"]["mode"] == "live" and delivery["mission"]["mode"] != "live":
                        raise ValueError("simulation or hybrid acceptance cannot earn live service revenue")
                if (
                    delivery["digest"] != event.execution_record_digest
                    or accepted_digest != event.acceptance_record_digest
                ):
                    raise Conflict("earning requires the exact current delivery and acceptance identities")
                row["earned_micro_usd"] += event.amount_micro_usd
            else:
                pending_key = "pending_" + event.allocation + "_refund_micro_usd"
                pending = row.get(pending_key, 0)
                capacity = {
                    "unearned": amounts["unearned_service"],
                    "earned": amounts["earned_revenue"],
                    "pass-through": amounts["pass_through_custody"],
                }[event.allocation]
                if action == "customer-refund-due" and event.allocation != "earned":
                    capacity -= pending
                elif action == "customer-refund" and event.allocation == "earned":
                    capacity += pending
                if event.amount_micro_usd > capacity:
                    raise ValueError("refund exceeds its remaining allocation")
                self._customer_evidence_unused(state, event.evidence_digest, cx)
                if action == "customer-refund-due":
                    row[pending_key] = pending + event.amount_micro_usd
                else:
                    row[pending_key] = max(0, pending - event.amount_micro_usd)
                    row["refunded_micro_usd"] += event.amount_micro_usd
                    if event.allocation == "earned":
                        row["earned_refund_micro_usd"] += event.amount_micro_usd
                evidence = event.evidence_digest
        self.journal.append(
            cx, "@flywheel-customer-event:" + identity, {"action": action, "signed": signed.model_dump()}
        )
        if evidence is not None:
            self.journal.append(cx, "@flywheel-customer-evidence:" + evidence, {"event_id": identity})

    def apply(self, signed: SignedEnvelope) -> dict[str, Any]:
        signed = SignedEnvelope.model_validate(signed.model_dump())
        payload = self.trust.verify(signed, "flywheel-cost-command", "accounting")
        if payload.get("journal_identity") != self.journal.identity or set(payload) != {
            "journal_identity",
            "operation_id",
            "action",
            "record",
        }:
            raise ValueError("accounting command must bind this journal and exact terms")
        operation_id = payload["operation_id"]
        if not isinstance(operation_id, str) or not 1 <= len(operation_id) <= 128:
            raise ValueError("bounded accounting operation identity required")
        binding = digest("flywheel-cost-command", payload)
        with self.journal.transaction() as cx:
            state = self.snapshot(cx)
            old = state["operations"].get(operation_id)
            if old is None:
                try:
                    old = self.journal.latest("@flywheel-accounting-operation:" + operation_id, cx)["binding"]
                except KeyError:
                    pass
            if old:
                if old != binding:
                    raise Conflict("accounting operation identity already has different terms")
                return state
            action, record = payload["action"], payload["record"]
            if action == "charge":
                charge = Charge.model_validate(record)
                if charge.activity_id in state["charges"]:
                    raise Conflict("activity already charged; A, B and C cannot overlap")
                self.require_open(state, charge.mission_id, charge.bucket)
                if charge.bucket == "A" and charge.mission_id in state["seals"]:
                    raise Conflict("sealed delivery cannot acquire an unreviewed additional charge")
                if charge.bucket == "B" and charge.mission_id in state.get("reuse_seals", {}):
                    raise Conflict("sealed incremental-cost record cannot acquire additional charges")
                self._reserve_paid_cost_evidence(charge.model_dump(), cx)
                state["charges"][charge.activity_id] = {**charge.model_dump(), "signed": signed.model_dump()}
            elif action == "resolve":
                charge = Charge.model_validate(record)
                previous = state["charges"].get(charge.activity_id)
                if previous is None or previous["accrued_micro_usd"] is not None or charge.accrued_micro_usd is None:
                    raise Conflict("only a recorded unknown charge may be resolved once")
                if any(previous[k] != getattr(charge, k) for k in ("mission_id", "bucket", "category")):
                    raise ValueError("reconciliation cannot move an activity between records or buckets")
                if charge.paid_micro_usd < previous["paid_micro_usd"]:
                    raise ValueError("reconciliation cannot reverse an already recorded payment")
                self._reserve_paid_cost_evidence(previous, cx)
                self._reserve_paid_cost_evidence(charge.model_dump(), cx)
                state["charges"][charge.activity_id] = {
                    **charge.model_dump(),
                    "signed": signed.model_dump(),
                    "original": previous,
                }
            elif action in {"customer-deposit", "customer-earn", "customer-refund-due", "customer-refund"}:
                self._customer(state, action, record, signed, cx)
            elif action == "payment":
                payment = Payment.model_validate(record)
                try:
                    self.journal.latest("@flywheel-customer-evidence:" + payment.evidence_digest, cx)
                except KeyError:
                    pass
                else:
                    raise Conflict("customer payment evidence already allocated")
                payments = state.setdefault("payments", {})
                if payment.payment_id in payments or any(
                    row["evidence_digest"] == payment.evidence_digest for row in payments.values()
                ):
                    raise Conflict("payment identity or allocated evidence already reconciled")
                for key in (
                    "@flywheel-payment:" + payment.payment_id,
                    "@flywheel-payment-evidence:" + payment.evidence_digest,
                ):
                    try:
                        self.journal.latest(key, cx)
                    except KeyError:
                        pass
                    else:
                        raise Conflict("payment identity or allocated evidence already reconciled")
                charge_record = state["charges"].get(payment.activity_id)
                if charge_record is None or charge_record["accrued_micro_usd"] is None:
                    raise Conflict("payment reconciliation requires an existing known accrual")
                if payment.amount_micro_usd > charge_record["accrued_micro_usd"] - charge_record["paid_micro_usd"]:
                    raise ValueError("payment exceeds the remaining accrued liability")
                charge_record["paid_micro_usd"] += payment.amount_micro_usd
                old_ids = charge_record.pop("payment_ids", [])
                charge_record["payment_count"] = charge_record.get("payment_count", len(old_ids)) + 1
                payments[payment.payment_id] = {**payment.model_dump(), "signed": signed.model_dump()}
                self._remember_payment(cx, payment.payment_id, payments[payment.payment_id])
                while len(payments) > MAX_PAYMENT_CACHE:
                    old_payment = next(iter(payments))
                    self._remember_payment(cx, old_payment, payments.pop(old_payment))
            elif action in {"capital", "collection", "offer", "invoice", "pending"}:
                if not isinstance(record, dict) or set(record) != {
                    "record_id",
                    "mission_id",
                    "amount_micro_usd",
                    "evidence_digest",
                }:
                    raise ValueError("money records require exact identity, mission, amount and evidence")
                IdentifierModel.model_validate(record)
                if record["record_id"] in state.get("customer_deposits", {}):
                    raise Conflict("customer receipt identity already allocated")
                if action in {"capital", "collection"}:
                    try:
                        self.journal.latest("@flywheel-customer-evidence:" + record["evidence_digest"], cx)
                    except KeyError:
                        pass
                    else:
                        raise Conflict("customer payment evidence already allocated")
                target = "capital" if action == "capital" else "receipts" if action == "collection" else "offers"
                if any(record["record_id"] in state[key] for key in ("capital", "receipts", "offers")):
                    raise Conflict("money record identity already used")
                if action in {"capital", "collection"} and any(
                    row["evidence_digest"] == record["evidence_digest"]
                    for key in ("capital", "receipts")
                    for row in state[key].values()
                ):
                    raise Conflict("incoming funding evidence already credited as capital or collection")
                state[target][record["record_id"]] = {**record, "kind": action, "signed": signed.model_dump()}
            elif action == "reserve":
                if not _is_exact_type(record, int) or not 0 <= record <= 10**15:
                    raise ValueError("reserve requires nonnegative integer USD micro-units")
                state["reserve_micro_usd"] = record
            elif action in {"seal", "seal-reuse", "seal-retention", "seal-investment"}:
                record = CompletenessSeal.model_validate(record).model_dump()
                mission = record["mission_id"]
                seals = (
                    state["seals"]
                    if action == "seal"
                    else state.setdefault("investment_seals" if action == "seal-investment" else "reuse_seals", {})
                )
                if mission in seals:
                    raise Conflict("delivery costs already sealed")
                rows = [
                    r
                    for r in state["charges"].values()
                    if r["mission_id"] == mission
                    and r["bucket"] == ("A" if action == "seal" else "C" if action == "seal-investment" else "B")
                ]
                if {r["category"] for r in rows} != CATEGORIES or any(r["accrued_micro_usd"] is None for r in rows):
                    raise ValueError("missing or unknown delivery costs prevent a complete-cost claim")
                seals[mission] = {**record, "signed": signed.model_dump()}
            else:
                raise ValueError("unsupported accounting action")
            self._remember_operation(cx, state, operation_id, binding, signed)
            self._persist(cx, state)
            if self.checkpoint is not None:
                self.checkpoint.advance(self.journal, cx)
            return state

    def report(self, mission_id: str | None = None, cx: Any = None) -> dict[str, Any]:
        state = self.snapshot(cx)
        all_rows = list(state["charges"].values())
        rows = [r for r in all_rows if mission_id is None or r["mission_id"] == mission_id]
        totals = {
            bucket: sum(r["accrued_micro_usd"] or 0 for r in rows if r["bucket"] == bucket)
            for bucket in ("A", "B", "C")
        }
        collected = sum(
            r["amount_micro_usd"]
            for r in state["receipts"].values()
            if mission_id is None or r["mission_id"] == mission_id
        )
        capital = sum(r["amount_micro_usd"] for r in state["capital"].values())
        all_collected = sum(r["amount_micro_usd"] for r in state["receipts"].values())
        paid = sum(r["paid_micro_usd"] for r in all_rows)
        obligations = sum(
            r["accrued_micro_usd"] - r["paid_micro_usd"] for r in all_rows if r["accrued_micro_usd"] is not None
        )
        unknown = any(r["accrued_micro_usd"] is None for r in all_rows)
        seal_sets = {"A": state["seals"], "B": state.get("reuse_seals", {}), "C": state.get("investment_seals", {})}
        present = {row["bucket"] for row in rows}
        bucket_complete = {}
        for bucket in ("A", "B", "C"):
            selected = [row for row in rows if row["bucket"] == bucket]
            missions = {row["mission_id"] for row in selected}
            bucket_complete[bucket] = (
                bool(missions)
                and missions <= set(seal_sets[bucket])
                and all(row["accrued_micro_usd"] is not None for row in selected)
            )
        complete = bool(present) and all(bucket_complete[bucket] for bucket in present)
        customer_rows = list(state.get("customer_deposits", {}).values())
        customer_modes = {
            mode: summarize(
                [
                    r
                    for r in customer_rows
                    if r["terms"]["mode"] == mode and (mission_id is None or r["terms"]["mission_id"] == mission_id)
                ]
            )
            for mode in MODES
        }
        live_customer = summarize([r for r in customer_rows if r["terms"]["mode"] == "live"])
        legacy_collected = collected
        collected += customer_modes["live"]["earned_revenue"]
        customer_cash = live_customer["net_cash"]
        customer_obligations = live_customer["customer_obligations"]
        obligations += customer_obligations
        return {
            "currency": "USD",
            "unit": "micro_usd",
            "costs": totals,
            "collected_revenue": collected,
            "delivery_profit": collected - totals["A"] if bucket_complete["A"] else None,
            "complete_cost_profit": collected - sum(totals.values()) if complete else None,
            "cash": capital + all_collected + customer_cash - paid,
            "obligations": None if unknown else obligations,
            "known_obligations": obligations,
            "reserve": state["reserve_micro_usd"],
            "available_funds": None
            if unknown
            else capital + all_collected + customer_cash - paid - obligations - state["reserve_micro_usd"],
            "legacy_attested_collections": legacy_collected,
            "accepted_service_revenue": customer_modes["live"]["earned_revenue"],
            "customer_funds_by_mode": customer_modes,
            "customer_obligations": customer_obligations,
            "customer_funds_basis": "Configured accounting attestations; only live-mode records affect operating funds. No bank verification or payment action.",
            "complete": complete,
            "bucket_complete": bucket_complete,
            "unknown_costs": unknown,
            "token_movements_included": False,
            "evidence_basis": "configured accounting signer attestations",
        }


class IdentifierModel(StrictModel):
    record_id: Identifier
    mission_id: Identifier
    amount_micro_usd: int = Field(ge=0, le=10**15)
    evidence_digest: Digest

